#!/bin/sh
# Flux LoRA on an 8GB card via kohya sd-scripts.
# 8GB recipe per docs/flux_train_network.md: --blocks_to_swap 28 + fp8 T5XXL.
# ai-toolkit could not do this: its 4-bit dequant has no fused kernel (see memory).
cd "C:/FlowDev/githubdevitems/comfyUIItems/sd-scripts" || exit 1
export PYTHONIOENCODING=utf-8
./venv/Scripts/accelerate.exe launch   --num_cpu_threads_per_process 1 --num_processes 1 --num_machines 1   --mixed_precision bf16 --dynamo_backend no   flux_train_network.py   --pretrained_model_name_or_path "C:/FlowDev/githubdevitems/comfyUIItems/ComfyUI/models/unet/flux1-dev.safetensors"   --clip_l "C:/FlowDev/githubdevitems/comfyUIItems/ComfyUI/models/text_encoders/clip_l.safetensors"   --t5xxl "C:/FlowDev/githubdevitems/comfyUIItems/ComfyUI/models/text_encoders/t5xxl_fp8_e4m3fn.safetensors"   --ae "C:/FlowDev/githubdevitems/comfyUIItems/ComfyUI/models/vae/ae.safetensors"   --dataset_config "C:/FlowDev/githubdevitems/comfyUIItems/lora_training/dataset_config_flux_win.toml"   --output_dir "C:/FlowDev/githubdevitems/comfyUIItems/lora_training/output"   --output_name son_ohwx_flux_v1   --save_model_as safetensors   --network_module networks.lora_flux   --network_dim 16 --network_alpha 16   --network_train_unet_only   --learning_rate 1e-4   --optimizer_type AdamW8bit   --lr_scheduler constant   --sdpa   --max_train_steps 1000   --save_every_n_steps 250   --mixed_precision bf16 --save_precision bf16   --gradient_checkpointing   --fp8_base   --blocks_to_swap 28   --guidance_scale 1.0   --timestep_sampling flux_shift   --model_prediction_type raw   --cache_latents --cache_latents_to_disk   --cache_text_encoder_outputs --cache_text_encoder_outputs_to_disk   --max_data_loader_n_workers 0   --seed 42
